/* @lc app=leetcode id=3528 lang=kotlin */ class Solution { fun baseUnitConversions(conversions: Array<IntArray>): IntArray = (conversions.size + 1).let { n -> conversions.groupBy { it[0] }.let { g -> LongArray(n).also { it[0] = 1L }.also { d -> generateSequence(listOf(0)) { f -> f.flatMap { u -> g[u].orEmpty().map { (_, v, w) -> v.also { d[v] = d[u] * w % 1_000_000_007L } } }.takeIf { it.isNotEmpty() } }.count() }.map { it.toInt() }.toIntArray() } } }